export function transferCandidates(gm={}){
 const season=Number(gm.season)||1,clubSeed=hashClub(gm.club||'커리어'),usedIds=new Set(gm.transferMarketPurchased||[]),usedNames=new Set((gm.squad||[]).map(p=>String(p.name||'').toLocaleLowerCase()));
 const pool=getAllImportedPlayers().filter(p=>p.club!==gm.club&&!usedNames.has(String(p.name||'').toLocaleLowerCase())&&!usedIds.has(`real-${p.id}`));
 const rand=marketRandom((season*7919+clubSeed*31+0x20261104)>>>0);
 const shufflePool=list=>{const ordered=[...list];for(let i=ordered.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[ordered[i],ordered[j]]=[ordered[j],ordered[i]];}return ordered;};const candidates=['공격','중원','수비','골키퍼'].flatMap(position=>shufflePool(pool.filter(p=>p.position===position)).slice(0,3)).map((p,i)=>{
  const rating=Number(p.currentRating??p.rating)||55,potential=Number(p.potentialRating??p.potential)||rating;
  const age=Number.isFinite(Number(p.age))?Number(p.age):null,ageForFee=age??26;
  const ageFactor=ageForFee>=32?.48:ageForFee<=20?1.12:ageForFee<=24?1.04:.94;
  const potentialFactor=1+Math.max(0,potential-rating)*.018;
  const fee=Math.round(Math.max(250000000,(rating-34)**2*105000000*ageFactor*potentialFactor)/10000000)*10000000;
  const id=`real-${p.id}`;
  return {...p,id,marketId:id,originalPlayerId:p.id,rating,potential,currentRating:rating,potentialRating:potential,age,fee,type:'실제 선수',style:p.specialAbilities?.join(' · ')||p.role||'균형형',moraleBoost:ageForFee>=32?10:ageForFee<=20?3:5,appearance:ageForFee>=32?'veteran':ageForFee<=20?'youth':'prime'};
 });
 const youth=(season>=2?(gm.youthPool||[]).filter(p=>!usedIds.has(p.id)&&!usedNames.has(String(p.name||'').toLocaleLowerCase())).map(p=>({...p,marketId:p.id,club:p.academyClub,type:'유스',fee:p.fee||Math.round((p.rating||50)*90000000)})):[]);
 return [...candidates,...youth];
}
export function makeTransferNegotiation(gm,playerId,offerAmount){
 const window=transferWindowStatus(gm);if(!window.open)return {error:'이적시장이 닫혀 있습니다.'};
 const player=transferCandidates(gm).find(p=>p.id===playerId||p.marketId===playerId);if(!player)return {error:'협상 대상 선수를 찾을 수 없습니다.'};
 const offer=Math.max(0,Math.round(Number(offerAmount)||0));if(!offer)return {error:'유효한 이적료를 입력하세요.'};
 const financialPower=Number(gm.transferBudget??gm.cash)||0;const european=String(gm.europe||'없음')!=='없음';const contract=Number(player.contractYears??2);const playingTime=Number(player.expectedPlayingTime??50);
 const premium=1.02+(european?.015:0)+(contract>=3?.08:contract<=1?-.07:0)+(playingTime<35?.06:0)+(financialPower>player.fee*3?.02:0);
 const asking=Math.round((Number(player.fee)||500000000)*premium/10000000)*10000000;
 if(offer>=asking){const signed=signPlayer(gm,{...player,fee:offer});return signed.error?signed:{gm:signed.gm,accepted:true,message:`${player.name} 영입 협상이 합의됐습니다.`};}
 const counter=Math.max(asking,Math.round(offer*1.12/10000000)*10000000);
 return {gm:{...gm,pendingTransferNegotiation:{playerId,player:{...player},offer,counterOffer:counter,askingPrice:asking,expiresDay:(gm.lastDay||0)+7}},counter:true,message:`구단이 ${money(counter)}의 역제안을 보냈습니다.`};
}
export function resolveTransferNegotiation(gm,decision){
 const pending=gm.pendingTransferNegotiation;if(!pending)return {error:'진행 중인 이적 협상이 없습니다.'};
 if(decision!=='accept')return {gm:{...gm,pendingTransferNegotiation:null},rejected:true,message:'이적 협상을 종료했습니다.'};
 const result=signPlayer({...gm,pendingTransferNegotiation:null},{...pending.player,fee:pending.counterOffer});
 return result.error?result:{gm:{...result.gm,pendingTransferNegotiation:null},accepted:true,message:`역제안 수락 · ${pending.player.name} 영입 완료`};
}
export function makeLoanOffer(gm,playerId,weeks=52){
 const window=transferWindowStatus(gm);if(!window.open)return {error:'임대 협상은 이적시장 기간에만 가능합니다.'};
 const player=transferCandidates(gm).find(p=>p.id===playerId||p.marketId===playerId);if(!player)return {error:'임대 대상 선수를 찾을 수 없습니다.'};
 if((gm.squad||[]).some(p=>p.loan?.marketId===playerId))return {error:'이미 임대 중인 선수입니다.'};
 const available=(gm.transferBudget??gm.cash)||0;const wageShare=Math.round((Number(player.wage)||Number(player.rating||50)*900000)*.55);const loanFee=Math.round((Number(player.fee)||0)*.035);
 if(available<loanFee)return {error:'임대료를 지불할 예산이 부족합니다.'};
 const strength=Number(gm.stats?.선수관리||40)+(Number(gm.morale||50)-50)*.12+(Number(player.rating||50)-Number(gm.teamRatings?.[player.position]||50))*.2;
 const accepted=player.type==='유스'||player.age<=22||strength>=48;
 if(!accepted)return {error:'선수 측이 출전 기회 부족을 우려해 임대 제안을 거절했습니다.'};
 const loaned={...player,id:`loan-${playerId}-${gm.season}-${gm.lastDay||0}`,marketId:playerId,loan:{marketId:playerId,from:player.club||player.academyClub||'원소속 구단',startSeason:gm.season,returnSeason:gm.season,loanFee,wageShare},fee:0,type:'임대 영입',fitness:100};
 const squad=assignSquadRoles([...(gm.squad||[]),loaned]);const teamRatings=Object.fromEntries(['공격','중원','수비','골키퍼'].map(pos=>{const group=squad.filter(p=>p.position===pos);return [pos,group.length?group.reduce((sum,p)=>sum+(Number(p.rating)||50),0)/group.length:50];}));
 return {gm:{...gm,squad,teamRatings,transferBudget:available-loanFee,youthPool:(gm.youthPool||[]).filter(p=>p.id!==playerId),loanLog:[...(gm.loanLog||[]),{name:player.name,from:loaned.loan.from,season:gm.season,loanFee,wageShare}],morale:clamp((gm.morale||70)+1)},accepted:true,message:`${player.name} 임대 영입 완료 · ${weeks}주 계약`};
}
export function setPlayerTransferStatus(gm,playerId,status){
 const allowed=['일반','이적 명단','임대 명단'];if(!allowed.includes(status))return {error:'올바르지 않은 선수 명단 상태입니다.'};
 let found=false;const squad=(gm.squad||[]).map(p=>{if(p.id!==playerId){return p;}found=true;return {...p,marketStatus:status};});
 return found?{gm:{...gm,squad},message:`선수 상태를 ${status}(으)로 변경했습니다.`}:{error:'선수를 찾을 수 없습니다.'};
}
export function resolveExternalOffer(gm,offerId,decision){const offer=(gm.pendingExternalOffers||[]).find(x=>x.id===offerId);if(!offer)return {error:'해당 구단 제안을 찾을 수 없습니다.'};const player=(gm.squad||[]).find(p=>p.id===offer.playerId);if(!player)return {error:'제안 대상 선수가 더 이상 선수단에 없습니다.'};const remaining=(gm.pendingExternalOffers||[]).filter(x=>x.id!==offerId);const ratingsFor=squad=>Object.fromEntries(['공격','중원','수비','골키퍼'].map(pos=>{const group=squad.filter(p=>p.position===pos);return [pos,group.length?group.reduce((sum,p)=>sum+(Number(p.rating)||50),0)/group.length:50];}));if(decision!=='accept'){const squad=(gm.squad||[]).map(p=>p.id===player.id?{...p,morale:clamp((p.morale??70)-(p.marketStatus==='일반'?2:5))}:p);return {gm:{...gm,pendingExternalOffers:remaining,squad,morale:clamp((gm.morale??70)-1),news:[`${player.name}의 ${offer.club} 제안을 거절했습니다. 선수의 이적 의사가 남아 있어 개인 사기가 소폭 하락했습니다.`,...(gm.news||[])]},message:`${player.name}의 제안을 거절했습니다. 선수 사기가 하락했습니다.`};}
 if(offer.kind==='임대'){const outgoingLoans=[...(gm.outgoingLoans||[]),{player:{...player},to:offer.club,startSeason:gm.season,returnSeason:gm.season+1,loanFee:offer.fee}];const squad=assignSquadRoles((gm.squad||[]).filter(p=>p.id!==player.id));return {gm:{...gm,squad,teamRatings:ratingsFor(squad),outgoingLoans,pendingExternalOffers:remaining,transferBudget:(gm.transferBudget??gm.cash??0)+offer.fee,loanLog:[...(gm.loanLog||[]),{name:player.name,to:offer.club,season:gm.season,loanFee:offer.fee}],news:[`${player.name}이(가) ${offer.club}(으)로 임대 이적했습니다.`,...(gm.news||[])]},message:`${player.name} 임대 이적 완료`};}
 const squad=assignSquadRoles((gm.squad||[]).filter(p=>p.id!==player.id));return {gm:{...gm,squad,teamRatings:ratingsFor(squad),transferBudget:(gm.transferBudget??gm.cash??0)+offer.fee,pendingExternalOffers:remaining,transferLog:[...(gm.transferLog||[]),`${player.name} → ${offer.club}`],news:[`${player.name}이(가) ${offer.club}(으)로 ${money(offer.fee)}에 이적했습니다.`,...(gm.news||[])]},message:`${player.name} 이적 완료 · ${money(offer.fee)} 수령`};}
export function generateExternalOffers(gm){if(!transferWindowStatus(gm).open)return gm;const existing=gm.pendingExternalOffers||[];const pendingIds=new Set(existing.map(x=>x.playerId));const squad=gm.squad||[];const clubNames=Object.keys(gm.aiClubFinance||{}).filter(x=>x!==gm.club);const pool=clubNames.length?clubNames:(gm.leagueClubs||[]).filter(x=>x!==gm.club);const offers=[...existing];for(const player of squad){if(pendingIds.has(player.id))continue;const listed=player.marketStatus==='이적 명단'||player.marketStatus==='임대 명단';const chance=listed?.42:.0045;if(Math.random()>chance)continue;const club=pool[Math.floor(Math.random()*pool.length)]||'해외 구단';const kind=player.marketStatus==='임대 명단'?'임대':player.marketStatus==='이적 명단'?(Math.random()<.78?'이적':'임대'):(Math.random()<.35?'임대':'이적');const base=Number(player.rating||55);const fee=kind==='임대'?Math.max(30000000,Math.round((base*1200000+Math.random()*180000000)/10000000)*10000000):Math.max(100000000,Math.round((base*base*6500000+Math.random()*500000000)/10000000)*10000000);offers.push({id:`external-${gm.season}-${gm.lastDay||0}-${player.id}-${offers.length}`,playerId:player.id,playerName:player.name,club,kind,fee,day:gm.lastDay||0,expiresDay:(gm.lastDay||0)+14});pendingIds.add(player.id);if(offers.length-existing.length>=3)break;}return {...gm,pendingExternalOffers:offers};}

function removeExpiredLoans(squad=[],season=1){return squad.filter(p=>!p.loan||Number(p.loan.returnSeason||season+1)>season);}
function injuryFrequencyForPlayer(player={}){const history=Array.isArray(player.injuryHistory)?player.injuryHistory.length:0;const minutes=Number(player.seasonMinutes||player.careerMinutes||0);if(history>=3)return '잔부상 많음';if(history>=1)return '보통';if(minutes>=2200)return '철강왕';if(['철강왕','보통','잔부상 많음'].includes(player.injuryFrequency))return player.injuryFrequency;const seed=String(player.id||player.name||'player').split('').reduce((a,c)=>a+c.charCodeAt(0),0)%100;return seed<22?'철강왕':seed<82?'보통':'잔부상 많음';}
const injuryFrequencyMultiplier={'철강왕':.62,'보통':1,'잔부상 많음':1.55};
